PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS user_accounts (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,password_salt TEXT NOT NULL,created_at TEXT NOT NULL,must_change_password INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS user_roles (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES user_accounts(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN ('admin','editor','viewer')) DEFAULT 'viewer',created_at TEXT NOT NULL,UNIQUE(user_id));
CREATE TABLE IF NOT EXISTS suppliers (id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL DEFAULT '',risk_category INTEGER NOT NULL DEFAULT 1,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,insurances TEXT NOT NULL DEFAULT '{}',certifications TEXT NOT NULL DEFAULT '{}',terms_and_conditions TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS non_conformities (id TEXT PRIMARY KEY,supplier_id TEXT NOT NULL REFERENCES suppliers(id) ON DELETE CASCADE,purchase_order_number TEXT NOT NULL DEFAULT '',project_number TEXT NOT NULL DEFAULT '',value_of_goods_affected REAL NOT NULL DEFAULT 0,result TEXT NOT NULL DEFAULT '',description TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY,value TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS contracts (id TEXT PRIMARY KEY,supplier_id TEXT NOT NULL,supplier_name TEXT NOT NULL,type TEXT NOT NULL DEFAULT 'IT Services',start_date TEXT NOT NULL,expiration_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Active',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contract_files (id TEXT PRIMARY KEY,contract_id TEXT NOT NULL REFERENCES contracts(id) ON DELETE CASCADE,file_name TEXT NOT NULL,file_path TEXT NOT NULL,file_size INTEGER NOT NULL DEFAULT 0,is_current INTEGER NOT NULL DEFAULT 1,uploaded_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contract_history (id TEXT PRIMARY KEY,contract_id TEXT NOT NULL REFERENCES contracts(id) ON DELETE CASCADE,change_type TEXT NOT NULL,previous_value TEXT,new_value TEXT NOT NULL,changed_by TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS onboarding_tokens (id TEXT PRIMARY KEY,supplier_id TEXT NOT NULL,token TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,used_at TEXT,created_by TEXT,created_at TEXT NOT NULL);
INSERT OR IGNORE INTO app_settings(key,value) VALUES ('internal_email','compliance@company.com');
